/**
 * スクロール入場アニメーションの IntersectionObserver フォールバック。
 *
 * `.reveal` の見た目は assets/reveal.css に 1 箇所だけ定義してある。
 * 一次実装は CSS Scroll-driven Animations（animation-timeline: view()）で、
 * ここは非対応ブラウザ（Safari等）向けのフォールバック。`.reveal` クラスを
 * 持つ要素に v-reveal を付けると、ビューポート進入時に `.revealed` を
 * one-shot 付与する。
 *
 * 二重発火しない仕組み:
 * - CSS側の transition は @supports not (animation-timeline: view())
 *   で囲まれているため、scroll-driven 対応ブラウザでは何も起きない
 * - JS側も supportsScrollTimeline() が真なら observer を作らない
 * - prefers-reduced-motion 時は CSS/JS とも無効（即表示）
 *
 * first fold の扱い:
 * - mount 時点で既にビューポート内にある要素は、scroll-driven 側では
 *   レンジ通過済みとして即表示になる。IO 側も体感を揃えるため、
 *   フェードさせずに即表示にする（ページ遷移の View Transition と
 *   二重にフェードしない）。
 */

/** CSS Scroll-driven Animations 対応判定 */
export function supportsScrollTimeline() {
  return (
    typeof CSS !== "undefined" && CSS.supports("animation-timeline: view()")
  );
}

function prefersReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

// 全要素で共有する one-shot Observer
let observer = null;

function getObserver() {
  if (observer) return observer;
  observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        reveal(entry.target);
      }
    },
    // reveal.css の scroll-driven 側（entry 0px 開始）に体感を合わせる。
    // - threshold 0: ビューポートより高い要素（記事本文・フォーム等）でも
    //   上端が入った時点で必ず発火する
    // - 上側の margin を巨大にして「既に通り過ぎた要素」も交差扱いにする。
    //   ページ内ジャンプ（ページ先頭へ戻る・スクロール復元等）で要素を飛び越えると
    //   IO は交差の変化を観測できず、透明のまま取り残されるため
    { threshold: 0, rootMargin: "100000px 0px -12% 0px" }
  );
  return observer;
}

/** 要素を立ち上げる（transition 付き）。完了後は素の状態に戻す */
function reveal(el) {
  observer?.unobserve(el);
  el.removeEventListener("focusin", el.__revealOnFocus);
  el.classList.add("revealed");
  // 入場完了後は reveal/revealed を外して素の状態に戻す
  // （.reveal の transition がホバー演出等と競合しないように）
  const cleanup = () => {
    el.classList.remove("reveal", "revealed");
    el.removeEventListener("transitionend", onEnd);
    clearTimeout(timer);
  };
  const onEnd = (e) => {
    if (e.target === el && e.propertyName === "opacity") cleanup();
  };
  el.addEventListener("transitionend", onEnd);
  const timer = setTimeout(cleanup, 1200); // transitionend が来ない場合の保険
}

/** mount 時点で既に見えている（または通り過ぎている）か。下端 12% のマージンは除く */
function isInFirstFold(el) {
  return el.getBoundingClientRect().top < window.innerHeight * 0.88;
}

/**
 * v-reveal ディレクティブ。
 * 使い方: <div class="stat-item reveal" v-reveal>
 */
export const vReveal = {
  mounted(el) {
    // scroll-driven 対応ならCSSに任せる / reduced-motion なら即表示（CSSが無効）
    if (supportsScrollTimeline() || prefersReducedMotion()) return;
    if (typeof IntersectionObserver === "undefined" || isInFirstFold(el)) {
      el.classList.remove("reveal"); // 即表示（フェードなし）
      return;
    }
    // Tab 移動などで画面外の要素にフォーカスが飛んだときは、IO を待たずに
    // 立ち上げる（透明なままフォーカスリングだけが出るのを防ぐ）
    el.__revealOnFocus = () => reveal(el);
    el.addEventListener("focusin", el.__revealOnFocus);
    getObserver().observe(el);
  },
  unmounted(el) {
    observer?.unobserve(el);
    el.removeEventListener("focusin", el.__revealOnFocus);
  },
};

/**
 * 要素が初めてビューポートに入ったら callback を1回だけ呼ぶ。
 * カウントアップ等、CSSに依存しない演出のトリガー用。
 * reduced-motion / IO 非搭載時は即時実行する。
 */
export function observeOnce(el, callback, options = {}) {
  if (
    prefersReducedMotion() ||
    typeof IntersectionObserver === "undefined"
  ) {
    callback();
    return () => {};
  }
  const io = new IntersectionObserver(
    (entries) => {
      if (entries.some((e) => e.isIntersecting)) {
        io.disconnect();
        callback();
      }
    },
    { threshold: 0.3, ...options }
  );
  io.observe(el);
  return () => io.disconnect();
}
