/**
 * View Transition の「実行中」フラグ。
 *
 * ページ遷移（router/index.js）とテーマ切替（composables/useColorTheme.js）の
 * 両方が document.startViewTransition を使う。同時に始めると後発が先発を
 * スキップさせて画面が飛ぶため、先発の実行中は後発側が通常の切り替えに
 * フォールバックする判断材料としてここを参照する。
 */
let pending = false;

export function setViewTransitionPending(value) {
  pending = value;
}

export function isViewTransitionPending() {
  return pending;
}
