import { ref } from "vue";
import {
  isViewTransitionPending,
  setViewTransitionPending,
} from "@/utils/viewTransition";

const isDark = ref(false);

// テーマ切替の見せ方（App.vue のスタイルと対になる）
// - theme-switching: View Transitions の円形ワイプ中。ワイプの中心・半径は
//   CSS 変数（--theme-x / --theme-y / --theme-r）で渡す
// - theme-transition: 非対応ブラウザ向けのクロスフェード中。全要素の
//   色トランジションはこのクラスが付いている間だけ有効
const WIPE_CLASS = "theme-switching";
const FADE_CLASS = "theme-transition";
const FADE_MS = 300;

// ブラウザ UI の色（<meta name="theme-color">）。App.vue の --c-bg と同じ値
const THEME_COLOR = { light: "#f7f2ea", dark: "#1c1813" };

let fadeTimer = 0;
// ワイプの世代番号。連打で前のワイプがスキップされたとき、
// 前の finished が後発のクラスを外さないようにする
let wipeSeq = 0;

function prefersReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function applyTheme(dark) {
  document.documentElement.classList.toggle("dark", dark);
  updateThemeColor(dark);
}

// index.html の <meta name="theme-color"> は media 属性で OS 設定に追従しているが、
// サイト側のトグルには追従しない。両方の meta に現在のテーマ色を書き、
// どちらの media が選ばれても同じ色になるようにする
function updateThemeColor(dark) {
  const color = dark ? THEME_COLOR.dark : THEME_COLOR.light;
  document
    .querySelectorAll('meta[name="theme-color"]')
    .forEach((meta) => meta.setAttribute("content", color));
}

function savedTheme() {
  try {
    return localStorage.getItem("theme");
  } catch (e) {
    return null;
  }
}

function saveTheme(dark) {
  try {
    localStorage.setItem("theme", dark ? "dark" : "light");
  } catch (e) {
    /* 保存できなくても表示の切り替えは行う */
  }
}

// 非対応ブラウザ: 全要素の色トランジションを FADE_MS だけ有効にしてクロスフェード
function switchWithFade(dark) {
  const html = document.documentElement;
  clearTimeout(fadeTimer);
  html.classList.add(FADE_CLASS);
  applyTheme(dark);
  fadeTimer = setTimeout(() => html.classList.remove(FADE_CLASS), FADE_MS);
}

// 対応ブラウザ: origin（トグルボタン）の中心から円形に新テーマを広げる。
// 連打で先発のワイプがスキップされても update コールバックは必ず呼ばれ、呼ばれる順も
// 保証されないため、引数の値ではなく「いま望まれている状態」(isDark) を適用する
function switchWithWipe(origin) {
  const html = document.documentElement;
  const rect = origin?.getBoundingClientRect?.();
  const x = rect ? rect.left + rect.width / 2 : window.innerWidth / 2;
  const y = rect ? rect.top + rect.height / 2 : window.innerHeight / 2;
  // 中心から最も遠い画面の角までの距離 = 画面全体を覆う半径
  const r = Math.hypot(
    Math.max(x, window.innerWidth - x),
    Math.max(y, window.innerHeight - y)
  );
  html.style.setProperty("--theme-x", `${x}px`);
  html.style.setProperty("--theme-y", `${y}px`);
  html.style.setProperty("--theme-r", `${r}px`);
  html.classList.add(WIPE_CLASS);

  const seq = ++wipeSeq;
  // ワイプ中はページ遷移側が View Transition を始めない（ワイプがスキップされて画面が飛ぶため）。
  // 新スナップショットはライブ描画なので、遷移そのものはワイプの下でそのまま進む
  setViewTransitionPending(true);
  const transition = document.startViewTransition(() =>
    applyTheme(isDark.value)
  );
  const cleanup = () => {
    // 連打で後発のワイプが走っていれば（先発はスキップされ finished は reject）、
    // 後始末はそちらに任せる
    if (seq !== wipeSeq) return;
    setViewTransitionPending(false);
    html.classList.remove(WIPE_CLASS);
    html.style.removeProperty("--theme-x");
    html.style.removeProperty("--theme-y");
    html.style.removeProperty("--theme-r");
  };
  // skip 時は finished が reject するので、両方の経路で後始末する
  transition.finished.then(cleanup, cleanup);
}

export function useColorTheme() {
  /**
   * @param {Element} [origin] ワイプの起点にする要素（トグルボタン）。
   *   省略時は画面中央から広がる
   */
  function toggle(origin) {
    const dark = !isDark.value;
    isDark.value = dark;
    saveTheme(dark);

    if (prefersReducedMotion()) {
      // 動きなしで即時切替（クロスフェードもしない）
      applyTheme(dark);
      return;
    }
    // ページ遷移の View Transition 中は、後発で始めると遷移が飛ぶのでフェードに逃がす
    if (!document.startViewTransition || isViewTransitionPending()) {
      switchWithFade(dark);
      return;
    }
    switchWithWipe(origin);
  }

  function init() {
    // FOUC防止のため実際のテーマ決定は public/index.html のインラインスクリプトが
    // 描画前に行っている（保存された選択 > OSの配色設定）。ここではその結果に
    // 状態を同期させるだけにして、判定ロジックの二重管理を避ける
    isDark.value = document.documentElement.classList.contains("dark");
    applyTheme(isDark.value);

    // ユーザーが明示的に選択するまでは、OSの配色設定の変更に追従する
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change", (e) => {
      if (savedTheme()) return;
      isDark.value = e.matches;
      applyTheme(e.matches);
    });
  }

  return { isDark, toggle, init };
}
